#pragma once
#include <juce_audio_utils/juce_audio_utils.h>
#include <set>
#include <cstdlib>
#include <cmath>
namespace NamPresets {
inline juce::Result save(const juce::File& file,juce::ValueTree state){juce::ValueTree root("TRACKSMITH_NAM_PRESET");root.setProperty("schema",1,nullptr);const auto path=state.getProperty("modelPath").toString();if(path.isNotEmpty()&&juce::File::isAbsolutePath(path))root.setProperty("modelRelative",juce::File(path).getRelativePathFrom(file.getParentDirectory()),nullptr);root.addChild(state.createCopy(),-1,nullptr);juce::TemporaryFile temporary(file);if(!temporary.getFile().replaceWithText(root.createXml()->toString())||!temporary.overwriteTargetFileWithTemporary())return juce::Result::fail("Could not save this preset. Choose a writable folder.");return juce::Result::ok();}
inline juce::Result load(const juce::File& file,juce::ValueTree& state){auto xml=juce::XmlDocument::parse(file);if(!xml)return juce::Result::fail("This is not a valid Tracksmith NAM preset.");auto root=juce::ValueTree::fromXml(*xml);if(!root.hasType("TRACKSMITH_NAM_PRESET")||int(root.getProperty("schema",0))!=1||root.getNumChildren()!=1||!root.getChild(0).hasType("AVRX_NAM"))return juce::Result::fail("Unsupported Tracksmith NAM preset.");auto next=root.getChild(0).createCopy();std::set<juce::String> ids;for(int i=0;i<next.getNumChildren();++i){auto child=next.getChild(i);auto id=child.getProperty("id").toString();if(!child.hasType("PARAM")||!ids.insert(id).second)return juce::Result::fail("Invalid preset parameter list.");double lo=0,hi=1;if(id=="input"){lo=-24;hi=24;}else if(id=="output"){lo=-24;hi=12;}else if(id=="threshold"){lo=-90;hi=-20;}else if(id=="release"){lo=20;hi=500;}else if(id=="bass"||id=="mid"||id=="treble"){lo=-12;hi=12;}else if(id=="midfreq"){lo=200;hi=4000;}else if(id=="highpass"){lo=20;hi=400;}else if(id!="gate"&&id!="bypass"&&id!="eq")return juce::Result::fail("Unknown preset parameter.");auto text=child.getProperty("value").toString().trim();char* end=nullptr;double value=std::strtod(text.toRawUTF8(),&end);if(text.isEmpty()||end==nullptr||*end!=0||!std::isfinite(value)||value<lo||value>hi)return juce::Result::fail("Invalid preset parameter value.");}const auto path=next.getProperty("modelPath").toString();if(path.isNotEmpty()){juce::File model;if(juce::File::isAbsolutePath(path))model=juce::File(path);if(!model.existsAsFile()){const auto relative=root.getProperty("modelRelative").toString();if(relative.isNotEmpty())model=file.getParentDirectory().getChildFile(relative);}if(!model.existsAsFile()||!model.hasFileExtension("nam"))return juce::Result::fail("The preset's .nam model is missing. Keep the model with your preset or load it from its original location.");next.setProperty("modelPath",model.getFullPathName(),nullptr);}state=next;return juce::Result::ok();}
}
